__NUXT_JSONP__("/inclusion/noticias/sin_contrato_laboral_en_mexico_90_de_jornaleras", (function(a,b,c,d,e){return {data:[{post:{slug:"sin_contrato_laboral_en_mexico_90_de_jornaleras",title:"Sin contrato laboral en México, 90% de jornaleras",date:"2025-09-26T19:17:38.766Z",img:"https:\u002F\u002Fucarecdn.com\u002F534f5fbe-4239-42f8-90fc-fe6c7842e5d4\u002F","img-alt":"Jornaleras agrícolas",autor:"Maritza Pérez, El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fpolitica\u002Fcontrato-laboral-mexico-90-jornaleras-20250926-778840.html",category:"inclusion",extracto:"Las organizaciones alertan que el gobierno mantiene una ambigüedad institucional sobre qué nivel de gobierno debe vigilar estas contrataciones, generando un vacío que perpetúa la impunidad.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En México, cerca del 90% de las jornaleras trabajan entre la informalidad, la violencia y condiciones laborales precarias, lo que deja al descubierto la explotación que enfrenta este sector de la población."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A través del informe “Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México”, las organizaciones UNIDAS, la alianza de Oxfam México, Ethos Innovación en Políticas Públicas, ProDESC y Fundación Avina, evidenciaron que nueve de cada 10 trabajadoras agrícolas del país no cuenta con un contrato escrito, pues son comunes los acuerdos verbales con intermediarios (camioneros, mayordomos, etc.), en los que sólo se respeta el pago y la jornada, dejando a un lado derechos como la seguridad social, vacaciones o aguinaldo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Se dijo que estas condiciones laborales son parte del abuso de los empleadores sobre la necesidad de las jornales de flexibilizar sus horarios debido a sus responsabilidades de cuidado, lo que lleva a muchas mujeres a aceptar estos trabajos sin contrato, situación que se complejiza para las trabajadoras migrantes e indígenas, quienes enfrentan mayor vulnerabilidad debido a la falta de redes de apoyo y de traductores, así como la necesidad de ingresos económicos inmediatos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:b,tag:"strong",props:{},children:[{type:a,value:"Señalan malas prácticas"}]}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, se estima que en nuestro país hay 368,000 trabajadoras agrícolas y el 86.6% de ellas no cuenta con seguridad social y que las empresas recurren a prácticas ilegales como entregar “pases” médicos en caso de accidentes laborales, que proporcionan atención médica eventual sin generar derechos y así evitar su afiliación al seguro social."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“La proporción de accidentes de trabajo reportados al IMSS de jornaleras agrícolas pasó del 6% en 2000 al 35% en 2024”, señala el documento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pese a estas cifras, las organizaciones alertan que el gobierno mantiene una ambigüedad institucional sobre qué nivel de gobierno debe vigilar estas contrataciones, generando un vacío que perpetúa la impunidad."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fsin_contrato_laboral_en_mexico_90_de_jornaleras",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-11-25T01:24:03.274Z")));